[
  {
    "statement": "Sowing native grass and forbs together is the most consistently effective method for establishing native forbs in degraded grasslands.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "Sowing native grass and forbs together increased forb species richness in 71% of cases.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "Sowing native grass and forbs together increased forb cover in multiple studies across different regions.",
    "citations": [
      "3432"
    ]
  },
  {
    "statement": "Sowing seeds at a higher density can enhance forb species richness and cover compared to standard seeding rates.",
    "citations": [
      "3405"
    ]
  },
  {
    "statement": "Adding topsoil before seeding increased plant species richness and sown species biomass.",
    "citations": [
      "3420"
    ]
  },
  {
    "statement": "The method of adding topsoil before seeding may be more costly than direct seeding approaches.",
    "citations": [
      "3420"
    ]
  },
  {
    "statement": "Planting grassland plants as seedlings showed high success rates for forbs in 83% of cases.",
    "citations": [
      "3399"
    ]
  },
  {
    "statement": "Planting grassland plants as seedlings requires more labor and materials than seeding methods.",
    "citations": [
      "3399"
    ]
  },
  {
    "statement": "The use of erosion blankets and irrigation showed mixed results for establishing native forbs.",
    "citations": [
      "3431",
      "3430"
    ]
  },
  {
    "statement": "The use of erosion blankets and irrigation add additional costs.",
    "citations": [
      "3431",
      "3430"
    ]
  },
  {
    "statement": "Direct seeding of native forbs, potentially at higher densities, emerges as the most cost-effective approach for forb establishment.",
    "citations": []
  },
  {
    "statement": "The cost-effectiveness of direct seeding is based on its consistent positive effects on forb establishment across multiple studies without requiring expensive additional treatments.",
    "citations": []
  }
]

[
  {
    "statement": "Adding fertilizer appears to be more consistently effective for increasing overall vegetation cover compared to inoculating soil with mycorrhiza.",
    "citations": []
  },
  {
    "statement": "Multiple studies show that fertilizer application increases total vegetation cover in various contexts.",
    "citations": []
  },
  {
    "statement": "A replicated study in the USA found that fertilizer initially increased vegetation cover when inoculating soil with mycorrhizal fungi before sowing seeds.",
    "citations": []
  },
  {
    "statement": "In the same replicated US study, after three years, vegetation cover did not differ between inoculated and non-inoculated areas.",
    "citations": []
  },
  {
    "statement": "In peatlands, fertilizing typically increased total vegetation cover.",
    "citations": []
  },
  {
    "statement": "In peatlands, fertilizing typically increased plant species richness.",
    "citations": []
  },
  {
    "statement": "A study in Iceland found that adding fertilizer alongside sowing seeds increased vegetation cover in two of three cases.",
    "citations": []
  },
  {
    "statement": "A study in Iceland found that adding fertilizer alongside sowing seeds increased shrub and tree cover in a majority of cases.",
    "citations": []
  },
  {
    "statement": "Mycorrhizal inoculation showed mixed results for increasing vegetation cover.",
    "citations": []
  },
  {
    "statement": "One study found no difference in vegetation cover after three years of mycorrhizal inoculation.",
    "citations": []
  },
  {
    "statement": "Another study showed no change in overall herbaceous species cover following mycorrhizal inoculation.",
    "citations": []
  }
]
